@layer component {
  .accordionItem {
    width: 100%;
    overflow: hidden;

    .summary {
      display: flex;
      position: relative;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
      border-top-right-radius: 0 !important;
      border-top-left-radius: 0 !important;
      background-color: var(--c-muted);
      padding: 1rem;
      padding-right: 3rem;
      font-weight: 900;
      font-size: 1.0625rem;
      line-height: 1.25rem;
      list-style: none;

      &::after {
        position: absolute;
        top: 50%;
        right: 1rem;
        transform: translateY(calc(-50% - 0.4rem)) rotate(45deg);
        border-width: 0 0.2rem 0.2rem 0;
        border-style: solid;
        border-color: currentColor;
        border-radius: var(--radius-alt);
        width: 1.25rem;
        height: 1.25rem;
        pointer-events: none;
        content: '';
      }

      &:hover {
        background-color: var(--c-primary);
      }

      &:focus-visible {
        outline: none;
        box-shadow: inset 0 0 0 0.25rem
          oklch(from color-mix(in oklch, var(--c-primary), var(--c-success)) 0.69 calc(c * 1.3) h);
        border-radius: var(--radius-alt);
      }
    }

    .content {
      position: relative;
      padding: 1rem;
      font-weight: 500;
    }

    &[aria-disabled] {
      opacity: 0.5;
      cursor: not-allowed;
    }

    &[open] {
      border-radius: var(--radius-alt);

      .summary {
        border-bottom: 0.125rem solid var(--c-border);
        border-radius: var(--radius);

        &::after {
          transform: translateY(calc(0.3rem - 50%)) rotate(45deg);
          border-width: 0.2rem 0 0 0.2rem;
          border-radius: var(--radius);
        }
      }
    }
  }
}

import { useCachedStyles } from '@/hook/useCachedStyles';
import { getCommonProps, type CommonProps } from '@/lib/utils';
import commonClasses from '@/style/common.module.css';
import type { ReactNode } from 'react';
import classes from './accordion.module.css';

const ACCORDION_CLASSES = `${commonClasses.base} ${classes.accordionItem}`;
export function AccordionItem({
  title,
  disabled,
  style,
  children,
  ...props
}: CommonProps<'details', { title?: ReactNode; disabled?: boolean }>) {
  const cStyles = useCachedStyles();

  return (
    <details style={{ ...cStyles, ...style }} {...getCommonProps(props, ACCORDION_CLASSES)} aria-disabled={disabled}>
      <summary className={classes.summary} inert={disabled}>
        {title}
      </summary>
      <div className={classes.content}>{children}</div>
    </details>
  );
}
